// ─── File: CapDemo.java ───
package com.bank.cap;

import java.util.logging.*;

public class CapDemo {
    private static final Logger log = Logger.getLogger("CAP");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Cluster cluster = new Cluster();
        CpStore money = new CpStore(cluster);   // CP for debits/credits
        ApStore display = new ApStore(cluster); // AP for balance display

        money.write("balance:SAV2001", "1000000");
        display.seed("balance:SAV2001", "1000000");

        // Network partition occurs
        cluster.setPartitioned(true);
        log.warning("NETWORK PARTITION");

        // CP money operation: REJECTED to preserve correctness
        try {
            money.transfer("balance:SAV2001", "50000");
        } catch (RuntimeException e) {
            log.warning(() -> "CP rejected transfer: " + e.getMessage());
        }

        // AP display read: still answers (possibly stale)
        log.info(() -> "AP balance display (possibly stale) = " + display.read("balance:SAV2001"));

        // Partition heals
        cluster.setPartitioned(false);
        log.info("PARTITION HEALED");

        // CP transfer now succeeds
        money.transfer("balance:SAV2001", "50000");
        log.info(() -> "CP money now = " + money.read("balance:SAV2001"));

        // AP reconciles with the authoritative value (eventual consistency)
        display.reconcile(money.read("balance:SAV2001"), "balance:SAV2001");
        log.info(() -> "AP after reconcile = " + display.read("balance:SAV2001"));
    }
}

