// ─── File: CpStore.java ───
package com.bank.cap;

import java.math.BigDecimal;
import java.util.*;

// CP: during a partition, reject writes/transfers to preserve consistency.
public class CpStore {
    private final Cluster cluster;
    private final Map<String,String> store = new HashMap<>();
    public CpStore(Cluster cluster) { this.cluster = cluster; }

    public void write(String key, String value) {
        requireQuorum();
        store.put(key, value);
    }
    public String read(String key) { return store.get(key); }

    public void transfer(String key, String amount) {
        requireQuorum();  // cannot guarantee latest state during partition → reject
        BigDecimal bal = new BigDecimal(store.get(key));
        store.put(key, bal.subtract(new BigDecimal(amount)).toPlainString());
    }
    private void requireQuorum() {
        if (cluster.isPartitioned())
            throw new IllegalStateException("no quorum during partition (CP)");
    }
}
```

